#include <bits/stdc++.h>
using namespace std;

struct FCards {
    long long mod = 998244353;

    long long power(long long base, long long exp) {
        long long result = 1;
        while (exp > 0) {
            if (exp & 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    void solve(int testNumber, istream& s, ostream& out) {
        int n, m, k;
        s >> n >> m >> k;
        int maxJ = min(n, k);
        vector<vector<long long>> dp(k + 1, vector<long long>(maxJ + 1, 0));
        dp[0][0] = 1;
        for (int i = 1; i <= k; i++) {
            for (int j = 1; j <= maxJ; j++) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j] * j % mod) % mod;
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1] * (n - j + 1) % mod) % mod;
            }
        }
        long long invm = power(m, mod - 2);
        long long res = 0;
        long long prob = 1;
        for (int i = 0; i <= maxJ; i++) {
            res = (res + dp[k][i] * prob % mod) % mod;
            prob = prob * invm % mod;
        }
        out << res << "\n";
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    FCards fc;
    fc.solve(1, cin, cout);
    return 0;
}

